/**
 * Deterministic feature extraction for the direct LightGBM prefilter.
 *
 * This is a byte-for-byte port of Abeeo's prompt_lightgbm.py feature functions.
 * Every choice here exists to match Python EXACTLY — the golden-vector test
 * (test/_fixtures/golden-vectors.json, generated by the Python reference)
 * fails loudly on any drift. Read prompt_lightgbm.py alongside this file.
 *
 * Parity hazards handled:
 *  - CRC32 uses the zlib polynomial, unsigned (matches Python zlib.crc32).
 *  - Word tokens use Unicode \w (Python re.UNICODE default): [\p{L}\p{M}\p{N}_].
 *  - isspace/isdigit/isupper/isalnum replicate Python's Unicode semantics via
 *    explicit code-point sets / Unicode property escapes; the golden test pins
 *    the resulting feature values.
 *  - Feature values are log1p'd hashed-ngram counts + raw structural stats.
 */

// --- CRC32 (zlib polynomial 0xEDB88320), unsigned 32-bit. ---
const CRC_TABLE = (() => {
  const table = new Uint32Array(256);
  for (let n = 0; n < 256; n += 1) {
    let c = n;
    for (let k = 0; k < 8; k += 1) {
      c = c & 1 ? 0xedb88320 ^ (c >>> 1) : c >>> 1;
    }
    table[n] = c >>> 0;
  }
  return table;
})();

export function crc32(str) {
  const bytes = Buffer.from(str, "utf-8");
  let crc = 0xffffffff;
  for (let i = 0; i < bytes.length; i += 1) {
    crc = CRC_TABLE[(crc ^ bytes[i]) & 0xff] ^ (crc >>> 8);
  }
  return (crc ^ 0xffffffff) >>> 0;
}

// --- Regexes mirrored from prompt_lightgbm.py (structural stat features). ---
const ROLE_RE = /(^|\n|\[|<)\s*(system|developer|assistant|tool|function|user)\s*[:>\]]/gi;
const CONTROL_TOKEN_RE = /<\|(?:im_start|im_end|eot_id|start_header_id|end_header_id|endoftext)\|>/g;
const BASE64_RE = /\b[A-Za-z0-9+/]{20,}={0,2}\b/g;
const HEX_RE = /\b(?:[0-9a-fA-F]{2}\s+){3,}[0-9a-fA-F]{2}\b/g;
const SPACED_WORD_RE = /(?<!\w)(?:[A-Za-z]\s+){3,}[A-Za-z](?!\w)/g;
const URL_RE = /https?:\/\/|www\./g;
const AI_TERMS_RE = /\b(ai|assistant|chatgpt|llm|model|system|developer|tool|prompt|instruction|policy|safety|guardrail)\b/gi;
const BYPASS_TERMS_RE =
  /\b(ignore|disregard|forget|override|bypass|disable|reveal|jailbreak|developer mode|dan|unrestricted|no longer bound|new instructions?)\b/gi;
// Python's re \w with re.UNICODE (the default for str patterns).
const WORD_TOKEN_RE = /[\p{L}\p{M}\p{N}_]+/gu;

function countMatches(re, value) {
  re.lastIndex = 0;
  let count = 0;
  while (re.exec(value) !== null) {
    count += 1;
    if (re.lastIndex === 0) break; // zero-width guard
  }
  return count;
}

// Code points for which Python str.isspace() returns True.
const PY_SPACE_CODEPOINTS = new Set([
  0x09, 0x0a, 0x0b, 0x0c, 0x0d, 0x1c, 0x1d, 0x1e, 0x1f, 0x20, 0x85, 0xa0, 0x1680, 0x2000, 0x2001, 0x2002, 0x2003,
  0x2004, 0x2005, 0x2006, 0x2007, 0x2008, 0x2009, 0x200a, 0x2028, 0x2029, 0x202f, 0x205f, 0x3000,
]);
function isSpace(ch) {
  return PY_SPACE_CODEPOINTS.has(ch.codePointAt(0));
}
function isDigit(ch) {
  // Python str.isdigit() also covers decimal digits beyond ASCII; \p{Nd}
  // captures the common case and is validated by the golden vectors.
  return /\p{Nd}/u.test(ch);
}
function isUpper(ch) {
  // Python str.isupper() is per-character here: cased uppercase letters.
  return /\p{Lu}/u.test(ch);
}
function isAlnum(ch) {
  return /[\p{L}\p{M}\p{N}]/u.test(ch);
}

/**
 * 20 structural features, in the exact order of _text_stats_values(). Iterates
 * by Unicode code point (Python iterates characters, not UTF-16 units).
 */
export function textStatsValues(text) {
  const value = String(text ?? "");
  const lower = value.toLowerCase();
  const chars = Array.from(value); // code points
  const length = chars.length;
  const words = value.match(WORD_TOKEN_RE) || [];

  let whitespace = 0;
  let punctuation = 0;
  let digits = 0;
  let uppercase = 0;
  for (const ch of chars) {
    const space = isSpace(ch);
    if (space) whitespace += 1;
    if (!isAlnum(ch) && !space) punctuation += 1;
    if (isDigit(ch)) digits += 1;
    if (isUpper(ch)) uppercase += 1;
  }

  const newlines = countChar(value, "\n");
  const denom = Math.max(length, 1);

  return [
    Math.log1p(length),
    Math.log1p(words.length),
    Math.log1p(newlines),
    whitespace / denom,
    punctuation / denom,
    digits / denom,
    uppercase / denom,
    countMatches(BASE64_RE, value),
    countMatches(HEX_RE, value),
    countMatches(SPACED_WORD_RE, value),
    countMatches(ROLE_RE, value),
    countMatches(CONTROL_TOKEN_RE, value),
    countMatches(URL_RE, value),
    countMatches(AI_TERMS_RE, value),
    countMatches(BYPASS_TERMS_RE, value),
    lower.includes("<system") || lower.includes("</system") ? 1 : 0,
    lower.includes("ignore previous") ? 1 : 0,
    lower.includes("developer mode") ? 1 : 0,
    lower.includes("system prompt") ? 1 : 0,
    lower.includes("new instructions") ? 1 : 0,
  ];
}

function countChar(value, ch) {
  let count = 0;
  for (let i = 0; i < value.length; i += 1) if (value[i] === ch) count += 1;
  return count;
}

/** Bound pathological inputs while preserving prefix and suffix (Python parity). */
export function boundedText(text, maxChars) {
  const value = String(text ?? "");
  const chars = Array.from(value);
  if (maxChars <= 0 || chars.length <= maxChars) return value;
  const prefix = Math.trunc(maxChars / 2);
  const suffix = maxChars - prefix;
  return chars.slice(0, prefix).join("") + "\n" + chars.slice(chars.length - suffix).join("");
}

function* iterCharNgrams(text, config) {
  const value = ` ${text.toLowerCase()} `;
  const chars = Array.from(value);
  const maxN = Math.min(config.char_ngram_max, chars.length);
  for (let n = config.char_ngram_min; n <= maxN; n += 1) {
    for (let i = 0; i + n <= chars.length; i += 1) {
      yield chars.slice(i, i + n).join("");
    }
  }
}

function* iterWordNgrams(text, config) {
  const words = text.toLowerCase().match(WORD_TOKEN_RE) || [];
  const maxN = Math.min(config.word_ngram_max, words.length);
  for (let n = 1; n <= maxN; n += 1) {
    for (let i = 0; i + n <= words.length; i += 1) {
      yield words.slice(i, i + n).join(" ");
    }
  }
}

/**
 * Sparse hashed feature map (column -> value) matching _direct_feature_counts.
 * char/word hashed n-gram counts are log1p'd; structural stats are appended
 * raw at the stat offset.
 */
export function directFeatureCounts(text, config) {
  const value = boundedText(text, config.max_chars);
  const features = new Map();

  if (config.char_hash_bins > 0) {
    for (const ngram of iterCharNgrams(value, config)) {
      const column = crc32("c:" + ngram) % config.char_hash_bins;
      features.set(column, (features.get(column) || 0) + 1);
    }
  }
  if (config.word_hash_bins > 0) {
    const wordOffset = config.char_hash_bins;
    for (const ngram of iterWordNgrams(value, config)) {
      const column = wordOffset + (crc32("w:" + ngram) % config.word_hash_bins);
      features.set(column, (features.get(column) || 0) + 1);
    }
  }
  for (const [column, count] of features) {
    features.set(column, Math.log1p(count));
  }

  const statOffset = config.char_hash_bins + config.word_hash_bins;
  const stats = textStatsValues(value);
  for (let offset = 0; offset < stats.length; offset += 1) {
    if (stats[offset]) features.set(statOffset + offset, stats[offset]);
  }
  return features;
}

/** Dense Float32Array row for a text (length = total feature count). */
export function directFeatureDense(text, config, totalFeatures) {
  const row = new Float32Array(totalFeatures);
  for (const [column, value] of directFeatureCounts(text, config)) {
    row[column] = value;
  }
  return row;
}

export function totalFeatureCount(config) {
  return config.char_hash_bins + config.word_hash_bins + textStatsValues("").length;
}
